<template><div class="min-h-screen bg-gray-50 flex"><aside class="w-56 bg-gray-900 text-white flex flex-col"><div class="p-5 border-b border-gray-800"><h1 class="text-lg font-black">HRMS</h1></div><nav class="flex-1 p-3 space-y-1"><router-link v-for="item in nav" :key="item.path" :to="item.path" class="flex items-center gap-3 px-4 py-2.5 rounded-xl text-sm font-medium transition" :class="$route.path.startsWith(item.path)?'bg-orange-500 text-white':'text-gray-300 hover:bg-gray-800'"><el-icon><component :is="item.icon" /></el-icon>{{ item.label }}</router-link></nav><div class="p-4 border-t border-gray-800"><p class="text-xs text-gray-400">{{ profile?.full_name || 'N/A' }}</p><p class="text-xs text-gray-500">{{ profile?.username }}</p></div></aside><main class="flex-1 overflow-auto"><header class="bg-white border-b px-6 py-3 flex items-center justify-between"><h2 class="text-lg font-bold text-gray-800">{{ pageTitle }}</h2><el-button size="small" @click="logout">Logout</el-button></header><div class="p-6"><router-view @update-title="(t:string)=>pageTitle=t" /></div></main></div></template><script setup lang="ts">import { computed,ref } from 'vue';import { useRouter } from 'vue-router';import { Warning,Search,Share,User,Setting } from '@element-plus/icons-vue';const router=useRouter();const pageTitle=ref('Dashboard');const profile=computed(()=>{try{return JSON.parse(localStorage.getItem('profile')||'{}')}catch{return{}}});const nav=[{path:'/attrition',label:'Attrition',icon:Warning},{path:'/talent',label:'Talent',icon:Search},{path:'/org',label:'Org',icon:Share},{path:'/profile',label:'Profile',icon:User},{path:'/settings',label:'Settings',icon:Setting}];function logout(){localStorage.clear();router.push('/login')}</script>
